/* ShaderScene: the canvas, filling its positioned ancestor.
   Placement and clipping belong to that ancestor, as with ShaderField: where
   a scene sits is a layout decision. The ground under the canvas is the
   page's, so a machine that cannot run WebGL2 shows the plain page. */

.ds-shader-scene {
  position: absolute;
  inset: 0;
  overflow: hidden;
  /* Scenery, never a target. */
  pointer-events: none;
  background-color: var(--color-bg-page-primary);
}

.ds-shader-scene__canvas {
  display: block;
  width: 100%;
  height: 100%;
}

'use client';

import React from 'react';
import { MOTION_RENDERER_WATCHDOG_MS } from '../../tokens/motion';
import { PASSES } from './passes';
import { coloursFor, createRenderer, glyphFontFor } from './renderer';
import { SCENES } from './scenes';
import { defaultsFor, type Values } from './types';
import './ShaderScene.css';

/* At most one drawing-buffer pixel per CSS pixel, unless the scene asks for
   more. The horizon and the rift are soft light, layered noise with no
   edge finer than a CSS pixel, so a 2x screen's extra pixels were invisible
   and quadrupled the fill: the horizon runs fourteen layered noise lookups
   per pixel, and a full-width band at 2x was six million pixels a frame. A
   scene that prints type declares its own cap (`pixelRatio` in scenes.ts),
   since type at 1x on a 2x screen is soft. */
const MAX_PIXEL_RATIO = 1;
/* 30fps, as ShaderField holds at rest: the scenes drift on cycles of
   tens of seconds, too slowly for 60fps to be visible, and every frame
   skipped is a whole scene's fill the GPU gives back to the page. */
const FRAME_MS = 1000 / 30;

/** The scenes ShaderScene paints. */
export type ShaderSceneId = 'horizon' | 'rift' | 'glyphs' | 'prism' | 'meteors' | 'waves' | 'aurora';

/**
 * How the scene resolved, the same three states ShaderField reports.
 * `pending` while the GL context comes up (bounded by a watchdog), `active`
 * once a frame has painted, `unavailable` when it is disabled or WebGL2
 * cannot run it.
 */
export type ShaderSceneStatus = 'pending' | 'active' | 'unavailable';

/** One finishing pass's setting: whether it runs, and its own settings. */
export type ShaderScenePassSetting = {
  /** Run the pass. Each pass has its own default. */
  on?: boolean;
  /** The pass's settings, merged over its defaults. */
  params?: Partial<Record<string, number>>;
};

/** Props owned by ShaderScene itself; everything else falls through to the root. */
type ShaderSceneOwnProps = {
  /** The scene to paint: `horizon`, a planet's limb at night, `rift`, a glowing tear, `glyphs`, soft light printed in type, `prism`, shafts of light split into a spectrum, `meteors`, a shower over a planet's edge, `waves`, a rolling sea of points, or `aurora`, ribbons of colour round a void. */
  scene?: ShaderSceneId;
  /**
   * The scene's settings, merged over its defaults (`SHADER_SCENES` lists each
   * scene's keys and ranges), so passing one changes one thing. Changing them
   * never rebuilds the GL state.
   */
  params?: Partial<Record<string, number>>;
  /**
   * The finishing passes (`scrim`, `vignette`, `fadeTop`, `fadeBottom`,
   * `grain`), each merged over its defaults.
   */
  passes?: Partial<Record<string, ShaderScenePassSetting>>;
  /** Scene seconds per second: how fast it moves. 0 holds it still. */
  speed?: number;
  /**
   * A ref the scene reads every frame in place of `params`, `passes` and
   * `speed`, for a host that tunes it by drag: writing the ref moves the
   * scene and renders nothing. Empty falls back to the props.
   */
  liveRef?: React.RefObject<Values | null>;
  /**
   * False never starts WebGL and reports `unavailable`, leaving the page
   * ground: the kill switch, as on ShaderField.
   */
  enabled?: boolean;
  /**
   * Called whenever the status changes. Drive a fallback from this: the scene
   * paints only the page ground when it cannot run, and what to show instead
   * is the caller's design decision.
   */
  onStatusChange?: (status: ShaderSceneStatus) => void;
  /** Additional CSS classes */
  className?: string;
};

export interface ShaderSceneProps
  extends ShaderSceneOwnProps,
    Omit<React.ComponentPropsWithRef<'div'>, keyof ShaderSceneOwnProps> {}

const DEFAULT_SPEED = 1.6;

/**
 * ShaderScene paints one of the system's shader scenes, a horizon, a rift,
 * a field of glyphs, a prism, a meteor shower, a sea of points or an aurora, in WebGL2, with finishing passes over it (a scrim, a vignette, top and
 * bottom fades to the page, film grain). Its colours are the background
 * field's roles (`--color-ambient-*`) read from the live cascade at the
 * scene, so it re-themes with `data-theme`, a preset or any scoped override,
 * and its fades melt into the page ground.
 *
 * Every scene is a night scene: it adds light over a dark ground. On a light
 * page each computes its light against a dark ground of its own and lays it
 * onto the page as a pale tint, so it reads as a soft dawn rather than a dark
 * block. Nothing here sets `data-theme`, which would hide a preset's colours.
 *
 * It is scenery, not interface. It fills its positioned ancestor and is inert
 * to pointer events and to assistive tech; give the ancestor the placement and
 * the clipping. It honours reduced motion in JavaScript, holding a still frame
 * that still answers its settings, and paints the page ground alone where
 * WebGL2 is unavailable.
 */
export function ShaderScene({
  scene = 'horizon',
  params,
  passes,
  speed = DEFAULT_SPEED,
  liveRef,
  enabled = true,
  onStatusChange,
  className = '',
  ref,
  ...rest
}: ShaderSceneProps) {
  const hostRef = React.useRef<HTMLDivElement | null>(null);
  const canvasRef = React.useRef<HTMLCanvasElement | null>(null);
  const definition = SCENES.find((s) => s.id === scene) ?? SCENES[0];

  /* The props merged over the defaults, kept in a ref the frame loop reads,
     so a new prop moves the scene without rebuilding the program. */
  const merged = React.useMemo<Values>(
    () => ({
      speed,
      scene: { ...defaultsFor(definition.params), ...params } as Record<string, number>,
      passes: Object.fromEntries(
        PASSES.map((pass) => {
          const setting = passes?.[pass.id];
          return [
            pass.id,
            {
              on: setting?.on ?? pass.on,
              params: { ...defaultsFor(pass.params), ...setting?.params } as Record<string, number>,
            },
          ];
        })
      ),
    }),
    [definition, params, passes, speed]
  );
  const mergedRef = React.useRef(merged);
  React.useEffect(() => {
    mergedRef.current = merged;
  }, [merged]);

  /* 'failed' and 'painted' come from the GL effect; the watchdog bounds a
     context that never paints, so pending can never be terminal. */
  const [gl, setGl] = React.useState<'pending' | 'failed' | 'painted'>('pending');
  const [gaveUp, setGaveUp] = React.useState(false);
  React.useEffect(() => {
    if (!enabled || gl !== 'pending') return;
    const timer = window.setTimeout(() => setGaveUp(true), MOTION_RENDERER_WATCHDOG_MS);
    return () => window.clearTimeout(timer);
  }, [enabled, gl]);
  const status: ShaderSceneStatus =
    !enabled || gl === 'failed'
      ? 'unavailable'
      : gl === 'painted'
        ? 'active'
        : gaveUp
          ? 'unavailable'
          : 'pending';
  const notify = React.useRef(onStatusChange);
  React.useEffect(() => {
    notify.current = onStatusChange;
  }, [onStatusChange]);
  React.useEffect(() => {
    notify.current?.(status);
  }, [status]);

  const setRef = (node: HTMLDivElement | null) => {
    hostRef.current = node;
    if (typeof ref === 'function') ref(node);
    else if (ref) ref.current = node;
  };

  React.useEffect(() => {
    if (!enabled) return;
    const host = hostRef.current;
    const canvas = canvasRef.current;
    const context = canvas?.getContext('webgl2', { antialias: false, alpha: false });
    const renderer = context ? createRenderer(context, definition, PASSES) : null;
    if (!host || !canvas || !renderer) {
      /* Reported from a frame, not the effect body, so the effect never
         sets state synchronously. */
      const failed = requestAnimationFrame(() => setGl('failed'));
      return () => cancelAnimationFrame(failed);
    }

    /* The colours, and for a type scene the face its ramp is drawn in: a
       preset can change both. */
    const applyColours = () => {
      renderer.setColours(coloursFor(host, definition));
      renderer.setGlyphs(glyphFontFor(host));
    };
    /* The drawing buffer is sized inside the frame that paints it, as
       ShaderField's is, never from the resize observer: setting a canvas's
       size clears it, and the observer runs after the frame's draw, so a
       buffer resized there reached the screen empty, a flash of the page
       ground on every step of a window drag. Compared first, since
       reallocating is the expensive part. Between throttled frames the old
       buffer stretches to the new box, which reads as nothing at all. */
    let ratio = 1;
    const fit = () => {
      ratio = Math.min(definition.pixelRatio ?? MAX_PIXEL_RATIO, window.devicePixelRatio || 1);
      const width = Math.max(1, Math.round(host.clientWidth * ratio));
      const height = Math.max(1, Math.round(host.clientHeight * ratio));
      if (canvas.width === width && canvas.height === height) return;
      canvas.width = width;
      canvas.height = height;
    };

    const still = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    let time = 20;
    let last = performance.now();
    let frame = 0;
    let painted = false;
    const draw = (now: number) => {
      frame = requestAnimationFrame(draw);
      if (painted && now - last < FRAME_MS - 1) return;
      const values = liveRef?.current ?? mergedRef.current;
      const dt = Math.min(0.1, (now - last) / 1000);
      last = now;
      if (!still) time += dt * values.speed;
      fit();
      renderer.draw(values, time, canvas.width, canvas.height, ratio);
      if (!painted) {
        painted = true;
        setGl('painted');
      }
    };
    /* The loop runs only near the screen, as ShaderField's does: it stops
       when the scene scrolls away and starts again 200px before it returns,
       so a page of stages draws only the ones in view. A hidden tab stops
       requestAnimationFrame by itself. */
    const start = () => {
      if (frame) return;
      last = performance.now();
      frame = requestAnimationFrame(draw);
    };
    const stop = () => {
      cancelAnimationFrame(frame);
      frame = 0;
    };

    applyColours();
    start();
    /* A code face still on its way draws the ramp in a fallback; draw it
       again once the fonts land. */
    let mounted = true;
    if (definition.glyphs) {
      document.fonts?.ready.then(() => {
        if (!mounted) return;
        renderer.setGlyphs('');
        renderer.setGlyphs(glyphFontFor(host));
      });
    }
    const visibilityObserver =
      typeof IntersectionObserver === 'undefined'
        ? null
        : new IntersectionObserver(
            (entries) => (entries[entries.length - 1].isIntersecting ? start() : stop()),
            { rootMargin: '200px 0px' }
          );
    visibilityObserver?.observe(host);

    /* A paused scene (scrolled away) still has to fill a box that changed:
       one frame at the time it stopped on, sized and painted together. */
    const sizeObserver = new ResizeObserver(() => {
      if (frame) return;
      fit();
      renderer.draw(liveRef?.current ?? mergedRef.current, time, canvas.width, canvas.height, ratio);
    });
    sizeObserver.observe(host);
    /* A theme flip, a preset and a live override (an inline custom property
       on the root) all re-read the colours. */
    const themeObserver = new MutationObserver(applyColours);
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['data-theme', 'data-brand', 'style'],
    });

    return () => {
      mounted = false;
      stop();
      visibilityObserver?.disconnect();
      sizeObserver.disconnect();
      themeObserver.disconnect();
      renderer.dispose();
    };
  }, [definition, liveRef, enabled]);

  const classes = ['ds-shader-scene', className].filter(Boolean).join(' ');

  return (
    <div {...rest} ref={setRef} className={classes} data-status={status} aria-hidden="true">
      {enabled && <canvas ref={canvasRef} className="ds-shader-scene__canvas" />}
    </div>
  );
}

/* The engine's data and helpers, re-exported below the component so the
   docs parser names the component after itself (see ShaderField.tsx), and
   so the barrel carries what a host needs to draw controls for a scene. */
export type {
  ParamSpec as ShaderSceneParamSpec,
  Scene as ShaderSceneDefinition,
  Pass as ShaderScenePass,
  Values as ShaderSceneValues,
  Recipe as ShaderSceneRecipe,
} from './types';
/* eslint-disable react-refresh/only-export-components */
export { SCENES as SHADER_SCENES } from './scenes';
export { PASSES as SHADER_PASSES } from './passes';
export { defaultsFor as shaderSceneDefaults } from './types';
export { bakeThumbnails as shaderSceneStills } from './renderer';
/* eslint-enable react-refresh/only-export-components */

/**
 * Builds one fragment shader from a scene and the passes: the uniforms
 * both declare, the common GLSL, the scene's `scene()`, each pass's
 * function, and a `main` that runs the scene, lays a night scene onto a
 * light page when it must (u_lightMode), then runs the light passes, the
 * encode and the srgb passes, each gated by its `u_<id>_on`.
 */
import { COMMON_GLSL } from "./common.glsl";
import type { Pass, Scene } from "./types";
import { MAX_COLOURS } from "./types";

export const VERTEX = /* glsl */ `#version 300 es
void main() {
  vec2 p = vec2((gl_VertexID << 1) & 2, gl_VertexID & 2);
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}
`;

/** Every float uniform the shader declares, for the canvas to set each frame. */
export function uniformNames(scene: Scene, passes: Pass[]) {
  return [
    ...scene.params.map((param) => `u_${param.key}`),
    ...passes.flatMap((pass) => [
      `u_${pass.id}_on`,
      ...pass.params.map((param) => `u_${pass.id}_${param.key}`),
    ]),
  ];
}

export function assemble(scene: Scene, passes: Pass[]) {
  const floats = uniformNames(scene, passes)
    .map((name) => `uniform float ${name};`)
    .join("\n");
  const call = (stage: Pass["stage"], target: string) =>
    passes
      .filter((pass) => pass.stage === stage)
      .map((pass) => `  if (u_${pass.id}_on > 0.5) ${target} = pass_${pass.id}(${target}, uv);`)
      .join("\n");

  return /* glsl */ `#version 300 es
precision highp float;

uniform vec2 u_size;
uniform float u_time;
uniform vec3 u_ground;   // the scene's ground: the page's, or a night scene's own
uniform vec3 u_page;     // the page's ground, which the passes fade to
uniform float u_lightMode; // 1: a night scene laid onto a light page
uniform float u_ratio;   // drawing-buffer pixels per CSS pixel
uniform vec3 u_col[${MAX_COLOURS}];
${scene.glyphs ? "uniform sampler2D u_glyphs;\nuniform float u_glyphCount;" : ""}
${floats}

out vec4 outColor;

${COMMON_GLSL}

${scene.glsl}

${passes.map((pass) => pass.glsl).join("\n")}

void main() {
  vec2 uv = gl_FragCoord.xy / u_size;
  vec3 lin = scene(uv, u_time);
  /* A night scene on a light page: the light it adds over its own dark
     ground is laid onto the page as a pale tint, its hue washed most of
     the way to white and never more than a light wash, so a horizon reads
     as a soft dawn on paper rather than a dark block on it. */
  if (u_lightMode > 0.5) {
    vec3 light = max(lin - u_ground, vec3(0.0));
    float peak = max(light.r, max(light.g, light.b));
    vec3 hue = light / max(peak, 1e-4);
    vec3 pastel = mix(hue, vec3(1.0), 0.3);
    float strength = clamp(pow(dot(light, vec3(0.2126, 0.7152, 0.0722)) * 4.0, 0.7), 0.0, 0.85);
    lin = mix(u_page, u_page * pastel, strength);
  }
${call("light", "lin")}
  vec3 srgb = pow(max(lin, vec3(0.0)), vec3(1.0 / 2.2));
  /* A one-step dither under everything, so wide ramps never band. */
  srgb += (float(ihash(uvec2(gl_FragCoord.xy)) & 255u) / 255.0 - 0.5) / 255.0;
${call("srgb", "srgb")}
  outColor = vec4(clamp(srgb, 0.0, 1.0), 1.0);
}
`;
}

/**
 * The GLSL every scene and pass can call: ShaderField's integer hash (no
 * fract(sin()) patterning, so no lines in the grain), value noise, fbm and
 * the one-sided Gaussian the horizon is built from.
 */
export const COMMON_GLSL = /* glsl */ `
uint ihash(uvec2 p) {
  p = p * uvec2(73333u, 7777u) ^ (p.yx >> 3u);
  uint h = p.x ^ (p.y * 2654435761u);
  h ^= h >> 15u;
  h *= 2246822519u;
  h ^= h >> 13u;
  return h;
}

float rnd(ivec2 p) {
  return float(ihash(uvec2(p)) >> 8) * (1.0 / 16777216.0);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  ivec2 c = ivec2(i) + 4096;
  return mix(
    mix(rnd(c), rnd(c + ivec2(1, 0)), u.x),
    mix(rnd(c + ivec2(0, 1)), rnd(c + ivec2(1, 1)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    s += a * vnoise(p);
    p = p * 2.02 + vec2(17.0, 9.0);
    a *= 0.5;
  }
  return s;
}

/* A one-sided Gaussian: one sigma above zero, another below. */
float lobe(float d, float above, float below) {
  float s = d > 0.0 ? above : below;
  return exp(-(d * d) / (2.0 * s * s));
}
`;

/**
 * The finishing passes, in the order they run. Light passes work on the
 * linear colour and pull it toward the page ground (`u_page`, the page's
 * own colour, which a night scene on a light page does not share with its
 * own `u_ground`); srgb passes work on
 * the encoded colour. Each is compiled into every shader and switched by
 * its `u_<id>_on` uniform, so toggling one never recompiles.
 */
import type { Pass } from "./types";

export const PASSES: Pass[] = [
  {
    id: "scrim",
    label: "Scrim",
    stage: "light",
    on: false,
    params: [{ key: "amount", label: "Amount", min: 0, max: 0.9, step: 0.01, default: 0.35 }],
    glsl: /* glsl */ `
vec3 pass_scrim(vec3 c, vec2 uv) {
  return mix(c, u_page, u_scrim_amount);
}`,
  },
  {
    id: "vignette",
    label: "Vignette",
    stage: "light",
    on: false,
    params: [
      { key: "amount", label: "Amount", min: 0, max: 1, step: 0.01, default: 0.5 },
      { key: "size", label: "Size", min: 0.2, max: 1.2, step: 0.01, default: 0.75 },
    ],
    glsl: /* glsl */ `
vec3 pass_vignette(vec3 c, vec2 uv) {
  vec2 q = (uv - 0.5) * vec2(u_size.x / u_size.y, 1.0);
  float v = smoothstep(u_vignette_size, u_vignette_size * 0.35, length(q));
  return mix(u_page, c, mix(1.0, v, u_vignette_amount));
}`,
  },
  {
    id: "fadeTop",
    label: "Fade the top",
    stage: "light",
    on: true,
    params: [
      { key: "start", label: "Starts at", min: 0.2, max: 0.95, step: 0.01, default: 0.43 },
      { key: "softness", label: "Softness", min: 0.3, max: 2, step: 0.01, default: 0.75 },
    ],
    glsl: /* glsl */ `
vec3 pass_fadeTop(vec3 c, vec2 uv) {
  float f = 1.0 - pow(smoothstep(u_fadeTop_start, 1.0, uv.y), u_fadeTop_softness);
  return mix(u_page, c, f);
}`,
  },
  {
    id: "fadeBottom",
    label: "Fade the bottom",
    stage: "light",
    on: true,
    params: [
      { key: "from", label: "Solid below", min: 0, max: 0.4, step: 0.01, default: 0.04 },
      { key: "to", label: "Clear above", min: 0.05, max: 0.7, step: 0.01, default: 0.3 },
    ],
    glsl: /* glsl */ `
vec3 pass_fadeBottom(vec3 c, vec2 uv) {
  float f = smoothstep(u_fadeBottom_from, max(u_fadeBottom_to, u_fadeBottom_from + 0.01), uv.y);
  return mix(u_page, c, f);
}`,
  },
  {
    id: "grain",
    label: "Film grain",
    stage: "srgb",
    on: true,
    params: [{ key: "amount", label: "Amount", min: 0, max: 0.4, step: 0.005, default: 0.198 }],
    glsl: /* glsl */ `
vec3 pass_grain(vec3 c, vec2 uv) {
  uvec2 gp = uvec2(gl_FragCoord.xy) + uvec2(
    uint(fract(u_time * 7.31) * 1024.0) * 7919u,
    uint(fract(u_time * 3.17) * 1024.0) * 104729u
  );
  float gr = float(ihash(gp) & 255u) / 255.0 - 0.5;
  return c + gr * u_grain_amount * 0.35;
}`,
  },
];

/**
 * The renderer both canvases share: the live stage and the thumbnail baker.
 * `createRenderer` compiles one scene with the passes into a program on a
 * WebGL2 context and returns a `draw` that sets every uniform from a values
 * object and paints one frame. `readColours` resolves a scene's tokens from
 * the live cascade. A scene that prints type (`glyphs`) also gets its ramp
 * as a strip texture, drawn in the theme's code face.
 */
import { assemble, uniformNames, VERTEX } from "./assemble";
import type { Pass, Scene, Values } from "./types";
import { MAX_COLOURS } from "./types";

export type Rgb = [number, number, number];

/** A near-black ground in linear RGB, which a night-only scene computes its light against on a light page. */
const NIGHT_GROUND: Rgb = [0.0015, 0.0018, 0.003];
export type Colours = {
  /** The ground the scene is painted against. */
  ground: Rgb;
  /** The page's own ground, which the passes fade to. */
  page: Rgb;
  /** A night scene on a light page, laid on as a pale tint. */
  lightMode: boolean;
  colours: Rgb[];
};

/** Resolves the page ground and a scene's tokens to linear RGB at `host`. */
export function readColours(host: HTMLElement, tokens: string[]): Colours {
  const probe = document.createElement("span");
  probe.style.display = "none";
  host.appendChild(probe);
  const dot = document.createElement("canvas");
  dot.width = 1;
  dot.height = 1;
  const ctx = dot.getContext("2d", { willReadFrequently: true });
  const lin = (c: number) => Math.pow(c / 255, 2.2);
  const read = (token: string): Rgb => {
    if (!ctx) return [0.2, 0.2, 0.2];
    probe.style.color = `var(${token})`;
    ctx.clearRect(0, 0, 1, 1);
    ctx.fillStyle = getComputedStyle(probe).color;
    ctx.fillRect(0, 0, 1, 1);
    const [r, g, b] = ctx.getImageData(0, 0, 1, 1).data;
    return [lin(r), lin(g), lin(b)];
  };
  const ground = read("--color-bg-page-primary");
  const colours = tokens.slice(0, MAX_COLOURS).map(read);
  probe.remove();
  return { ground, page: ground, lightMode: false, colours };
}

/**
 * A scene's colours for a surface: read from the cascade. A night-only
 * scene on a light page computes its light against a dark ground of its
 * own, and the shader lays that light onto the page as a pale tint
 * (u_lightMode), so its masks still fade to the page and the theme stays
 * light.
 */
export function coloursFor(host: HTMLElement, scene: Scene): Colours {
  const colours = readColours(host, scene.colours);
  const pageIsDark = document.documentElement.getAttribute("data-theme") === "dark";
  if (scene.mode === "dark" && !pageIsDark) {
    colours.ground = NIGHT_GROUND;
    colours.lightMode = true;
  }
  return colours;
}

/** The face a scene's type is drawn in: the theme's code face at `host`. */
export function glyphFontFor(host: HTMLElement) {
  return getComputedStyle(host).getPropertyValue("--font-family-code").trim() || "monospace";
}

const GLYPH_W = 48;
const GLYPH_H = 80;

/** A scene's ramp as one strip, a character per cell, white on black. */
function drawGlyphs(ramp: string, font: string) {
  const glyphs = [...ramp];
  const strip = document.createElement("canvas");
  strip.width = GLYPH_W * glyphs.length;
  strip.height = GLYPH_H;
  const ctx = strip.getContext("2d");
  if (ctx) {
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, strip.width, strip.height);
    ctx.fillStyle = "#fff";
    ctx.font = `700 ${GLYPH_H * 0.78}px ${font}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    glyphs.forEach((glyph, i) => ctx.fillText(glyph, (i + 0.5) * GLYPH_W, GLYPH_H * 0.52));
  }
  return { strip, count: glyphs.length };
}

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.warn(gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

/** The value a uniform takes from a values object. */
function valueOf(values: Values, passes: Pass[], name: string): number {
  for (const pass of passes) {
    const prefix = `u_${pass.id}_`;
    if (!name.startsWith(prefix)) continue;
    const state = values.passes[pass.id];
    const key = name.slice(prefix.length);
    if (key === "on") return state?.on ? 1 : 0;
    return state?.params[key] ?? 0;
  }
  return values.scene[name.slice(2)] ?? 0;
}

export function createRenderer(gl: WebGL2RenderingContext, scene: Scene, passes: Pass[]) {
  const vs = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const fs = compile(gl, gl.FRAGMENT_SHADER, assemble(scene, passes));
  const program = gl.createProgram();
  if (!vs || !fs || !program) return null;
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.useProgram(program);
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);

  const at = (name: string) => gl.getUniformLocation(program, name);
  const uSize = at("u_size");
  const uTime = at("u_time");
  const uGround = at("u_ground");
  const uPage = at("u_page");
  const uLightMode = at("u_lightMode");
  const uCols = at("u_col");
  const uRatio = at("u_ratio");
  const uGlyphCount = at("u_glyphCount");
  const floats = uniformNames(scene, passes).map((name) => [name, at(name)] as const);
  const glyphTexture = scene.glyphs ? gl.createTexture() : null;
  let glyphFont = "";

  return {
    setColours({ ground, page, lightMode, colours }: Colours) {
      gl.uniform3fv(uGround, ground);
      gl.uniform3fv(uPage, page);
      gl.uniform1f(uLightMode, lightMode ? 1 : 0);
      const flat = new Float32Array(MAX_COLOURS * 3);
      colours.forEach((rgb, i) => flat.set(rgb, i * 3));
      gl.uniform3fv(uCols, flat);
    },
    /** Draws a type scene's ramp in `font`; a scene without one ignores it. */
    setGlyphs(font: string) {
      if (!scene.glyphs || !glyphTexture || font === glyphFont) return;
      glyphFont = font;
      const { strip, count } = drawGlyphs(scene.glyphs, font);
      gl.bindTexture(gl.TEXTURE_2D, glyphTexture);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, strip);
      gl.generateMipmap(gl.TEXTURE_2D);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.uniform1f(uGlyphCount, count);
    },
    draw(values: Values, time: number, width: number, height: number, ratio = 1) {
      gl.viewport(0, 0, width, height);
      gl.uniform2f(uSize, width, height);
      gl.uniform1f(uRatio, ratio);
      gl.uniform1f(uTime, time);
      for (const [name, location] of floats) gl.uniform1f(location, valueOf(values, passes, name));
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    },
    dispose() {
      gl.deleteTexture(glyphTexture);
      gl.deleteVertexArray(vao);
      gl.deleteProgram(program);
      gl.deleteShader(vs);
      gl.deleteShader(fs);
    },
  };
}

/**
 * Paints each recipe once on a throwaway context and returns the pictures
 * as data URLs, then releases the context, so the tiles cost no live GPU
 * context of their own and the page keeps one.
 */
export function bakeThumbnails(
  host: HTMLElement,
  jobs: { scene: Scene; values: Values }[],
  passes: Pass[],
  width: number,
  height: number
): string[] {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const gl = canvas.getContext("webgl2", { antialias: false, alpha: false, preserveDrawingBuffer: true });
  if (!gl) return jobs.map(() => "");
  const urls = jobs.map(({ scene, values }) => {
    const renderer = createRenderer(gl, scene, passes);
    if (!renderer) return "";
    renderer.setColours(coloursFor(host, scene));
    renderer.setGlyphs(glyphFontFor(host));
    renderer.draw(values, 20, width, height);
    const url = canvas.toDataURL("image/jpeg", 0.85);
    renderer.dispose();
    return url;
  });
  gl.getExtension("WEBGL_lose_context")?.loseContext();
  return urls;
}

/**
 * ShaderScene's scenes. Each is one look: its GLSL `scene()`, its settings
 * as typed data (so a host can draw a slider per setting) and the colour
 * roles it reads. All read the background field's roles
 * (`--color-ambient-*`), the ones a theme tunes for ambient shaders, so a
 * theme recolours them with no wiring.
 */
import type { Scene } from './types';

/**
 * The horizon, ported from /labs/horizon as a scene: a planet's limb at
 * night with a fixed sun at the apex, soft layers of light along the arc,
 * a hazy world of land and cloud below, and deep ocean blue further down.
 * The horizon lab's own fades and grain are passes here, so they can be switched
 * and tuned like any other scene's.
 */
export const horizon: Scene = {
  id: "horizon",
  label: "Horizon",
  description: "A planet's limb at night, a fixed sun at the apex, a hazy world and ocean below.",
  mode: "dark",
  /* The background field's roles, the ones a preset tunes for ambient
     shaders and a DESIGN.md import rewrites from the action colour: in the
     base theme they are cobalt, amber, coral and gold, so the horizon's own
     look is unchanged, and an import recolours it with the field. */
  colours: [
    "--color-ambient-4",
    "--color-ambient-6",
    "--color-ambient-5",
    "--color-ambient-1",
  ],
  params: [
    { key: "crown", label: "Horizon height", min: 0.15, max: 0.75, step: 0.01, default: 0.4 },
    { key: "curve", label: "Flatness", min: 1.5, max: 10, step: 0.1, default: 5 },
    { key: "warp", label: "Flow", min: 0, max: 0.2, step: 0.005, default: 0.07 },
    { key: "glow", label: "Glow", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "clouds", label: "Clouds", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "ocean", label: "Ocean", min: 0, max: 2.5, step: 0.01, default: 1 },
    { key: "beam", label: "Beam", min: 0, max: 2.5, step: 0.01, default: 1 },
  ],
  glsl: /* glsl */ `
#define u_scatter u_col[0]
#define u_halo u_col[1]
#define u_rim u_col[2]
#define u_sun u_col[3]

vec3 scene(vec2 uv, float t) {
  float aspect = u_size.x / u_size.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y);

  vec2 q = vec2(
    fbm(p * 1.4 + vec2(0.0, t * 0.03)),
    fbm(p * 1.4 + vec2(5.2, 1.3) - t * 0.024)
  );
  vec2 w = p + u_warp * (q - 0.5);

  float crown = u_crown;
  float radius = u_curve * max(aspect, 1.0);
  vec2 centre = vec2(0.0, crown - radius);
  vec2 wl = p + u_warp * 0.17 * (q - 0.5);
  float d = length(wl - centre) - radius;

  float halfW = 0.5 * aspect;
  float sunX = exp(-pow(w.x, 2.0) / (2.0 * 0.28 * 0.28));
  float wide = exp(-pow(w.x, 2.0) / (2.0 * 0.75 * 0.75));
  float energy = (0.4 + 0.45 * wide + 0.9 * sunX) * u_glow;
  float side = clamp(abs(w.x) / halfW, 0.0, 1.0);

  float curtain = fbm(vec2(w.x * 5.0 + t * 0.05, d * 1.2 - t * 0.02));
  float band = fbm(vec2(w.x * 1.2 - t * 0.035, d * 11.0 + t * 0.015));
  float veil = fbm(vec2(w.x * 2.2 + t * 0.02, d * 3.5 - t * 0.01) + q * 1.5);

  vec3 amber = mix(u_halo, u_sun, 0.35);
  vec3 light = vec3(0.0);
  light += u_scatter * lobe(d - 0.02, 0.24, 0.12) * (0.12 + 0.08 * curtain) * (0.7 + 0.5 * energy);
  light += mix(u_scatter, vec3(1.0), 0.35) * lobe(d - 0.05, 0.12, 0.05)
    * (0.06 + 0.16 * smoothstep(0.35, 0.8, curtain)) * energy;
  light += mix(amber, u_rim, side * 0.4) * lobe(d - 0.01, 0.07, 0.045) * (0.35 + 0.35 * band) * energy;
  light += mix(amber, u_sun, 0.3) * lobe(d, 0.02, 0.012) * (0.45 + 0.2 * band) * energy;
  light += mix(amber, vec3(1.0), 0.35) * lobe(d - 0.002, 0.006, 0.003) * 0.55 * energy;
  light += u_rim * lobe(d + 0.03, 0.05, 0.07) * (0.22 + 0.18 * veil) * (0.6 + 0.5 * energy);
  light *= 1.0 - 0.8 * smoothstep(0.0, -0.4, d);

  float below = max(-d, 0.0);
  float onGround = smoothstep(0.002, -0.012, d);
  float z = 1.0 / (below * 2.4 + 0.08);
  vec2 sp = vec2(w.x * z * 0.55, z * 0.5);
  float drift = t * 0.018;

  vec2 lp = sp * 0.9 + vec2(drift * 0.4, drift);
  float land = fbm(lp + 1.4 * vec2(fbm(lp * 0.7 + 3.1), fbm(lp * 0.7 + 8.4)));
  land = smoothstep(0.42, 0.72, land);
  vec2 cp = sp * 1.6 + vec2(-drift * 1.6, drift * 1.3);
  float cloud = fbm(cp + 2.0 * vec2(fbm(cp * 0.5 + q), fbm(cp * 0.5 - q + 5.0)));
  vec2 fp = sp * 3.4 + vec2(-drift * 2.4, drift * 1.8) + q * 0.8;
  float fine = fbm(fp + 1.2 * vec2(fbm(fp * 0.6 + 2.3), fbm(fp * 0.6 + 6.1)));
  cloud = smoothstep(0.42, 0.8, cloud);
  cloud = clamp(cloud + 0.55 * smoothstep(0.5, 0.85, fine), 0.0, 1.0) * u_clouds;
  float streaks = fbm(vec2(sp.x * 0.35 - drift * 2.0, sp.y * 4.0));

  float reach = exp(-below / 0.45);
  float near = exp(-below / 0.07);
  vec3 world = vec3(0.0);
  world += mix(u_ground, u_scatter, 0.5) * land * 0.14 * (0.35 + reach);
  world += mix(u_scatter, vec3(1.0), 0.3) * cloud * 0.48 * reach;
  world += mix(u_rim, amber, 0.4) * cloud * near * 0.6 * energy;
  world += u_scatter * streaks * 0.08 * reach;

  vec2 src = vec2(0.0, crown - 0.005);
  vec2 r = p - src;
  float ang = atan(r.x, -r.y);
  float shafts = smoothstep(0.2, 0.95, fbm(vec2(ang * 1.6, 3.7)));
  float cone = exp(-pow(ang, 2.0) / (2.0 * 0.55 * 0.55));
  float dist = length(r);
  float beams = shafts * cone * exp(-dist / 0.6);
  vec3 beamColour = mix(mix(amber, u_sun, 0.3), u_scatter, smoothstep(0.08, 0.45, dist) * 0.7);
  world += beamColour * beams * 0.45 * (0.65 + 0.5 * cloud) * u_beam;

  float bloomSky = exp(-dot(r, r) / (2.0 * 0.09 * 0.09));
  float bloomWide = exp(-dot(r, r) / (2.0 * 0.28 * 0.28));
  light += mix(u_sun, vec3(1.0), 0.35) * (bloomSky * 0.45 + bloomWide * 0.12) * u_glow;
  world += mix(u_sun, amber, 0.4) * bloomWide * 0.12 * u_glow;

  float sea = smoothstep(0.02, 0.16, below) * (1.0 - 0.65 * land);
  vec3 deep = mix(u_scatter, u_ground, 0.2);
  world *= mix(vec3(1.0), normalize(u_scatter + 0.05) * 1.2, smoothstep(0.08, 0.3, below) * 0.5);
  world += deep * sea * (0.16 + 0.07 * streaks + 0.05 * veil + 0.14 * cloud) * u_ocean;

  light += world * onGround;
  return u_ground + light;
}
`,
};

/**
 * The rift, after /labs/rift, as a soft shader rather than streaming type:
 * a glowing vertical tear in the page that opens widest at its middle and
 * narrows to a seam at either end, a bright core inside a wide glow and a
 * faint haze, and streaks of light drawn in toward it from both sides. The
 * tear's line wanders slowly, and the colour runs from one ambient tone at
 * the top to another at the bottom, the rift lab's own pair.
 */
export const rift: Scene = {
  id: "rift",
  label: "Rift",
  description: "A glowing tear in the page, opening at its middle, light streaming in.",
  mode: "dark",
  colours: ["--color-ambient-2", "--color-ambient-3", "--color-ambient-1"],
  params: [
    { key: "offset", label: "Position", min: -0.45, max: 0.45, step: 0.01, default: 0 },
    { key: "open", label: "Opening", min: 0, max: 1.5, step: 0.01, default: 0.8 },
    { key: "glow", label: "Glow", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "wave", label: "Wander", min: 0, max: 1, step: 0.01, default: 0.4 },
    { key: "streaks", label: "Streaks", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "flow", label: "Flow", min: 0, max: 0.3, step: 0.005, default: 0.08 },
  ],
  glsl: /* glsl */ `
#define u_from u_col[0]
#define u_to u_col[1]
#define u_spark u_col[2]

vec3 scene(vec2 uv, float t) {
  float aspect = u_size.x / u_size.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);

  vec2 q = vec2(
    fbm(p * 1.6 + vec2(0.0, t * 0.03)),
    fbm(p * 1.6 + vec2(5.2, 1.3) - t * 0.025)
  );

  /* The tear's line, wandering slowly along its length. */
  float cx = u_offset * aspect + u_wave * 0.35 * (fbm(vec2(p.y * 1.6, t * 0.04)) - 0.5);
  float dx = p.x - cx + u_flow * (q.x - 0.5);
  float ady = abs(dx);

  /* Widest at the middle, a seam at the ends. */
  float open = u_open * exp(-(p.y * p.y) / (2.0 * 0.3 * 0.3));
  float coreW = 0.006 + 0.01 * open;
  float glowW = 0.07 + 0.2 * open;
  float core = exp(-(dx * dx) / (2.0 * coreW * coreW)) * (0.25 + 0.6 * open);
  float glow = exp(-(dx * dx) / (2.0 * glowW * glowW)) * (0.25 + 0.75 * open);
  float haze = exp(-ady / 0.38) * (0.4 + 0.6 * open);

  /* Streaks drawn in toward the tear: bands that move inward over time. */
  float s = fbm(vec2(ady * 3.0 + t * 0.35, p.y * 42.0 + q.y * 3.0));
  float streak = smoothstep(0.58, 0.86, s) * exp(-ady / 0.2) * smoothstep(0.01, 0.06, ady) * u_streaks;

  vec3 colour = mix(u_from, u_to, smoothstep(-0.45, 0.45, p.y + (q.y - 0.5) * 0.4));
  vec3 light = vec3(0.0);
  light += colour * glow * 0.7 * u_glow;
  light += colour * haze * 0.1;
  light += mix(colour, vec3(1.0), 0.45) * core * 0.7 * u_glow;
  light += mix(colour, u_spark, 0.35) * streak * 0.22;
  return u_ground + light;
}
`,
};

/**
 * The glyph field: soft light printed in type.
 * Two layers in one pass. Six stretched Gaussian lights (a wide haze, a
 * bloom, a white-hot core, one long thin streak and two blooms below) are
 * added over the ground and tone-mapped, so where colours stack the core
 * burns to white; they drift, breathe and roll on slow travelling swells.
 * Then the screen is cut into character cells: each cell reads the light at
 * its centre and prints a glyph from the ramp that thickens with the
 * brightness, lighter than what is under it. Below a floor nothing prints,
 * so the type gathers on the light and scatters to dots at its edge.
 * Nothing snaps: the scatter eases from one roll to the next, and a cell
 * crossing a step of the ramp dissolves between the two glyphs.
 */
export const glyphs: Scene = {
  id: "glyphs",
  label: "Glyphs",
  description: "Soft light printed in type: a streak and its blooms read through characters that thicken with the brightness.",
  mode: "dark",
  colours: [
    "--color-ambient-4",
    "--color-ambient-2",
    "--color-ambient-1",
    "--color-ambient-3",
    "--color-ambient-5",
  ],
  glyphs: ".·xxXXSO0#@",
  /* Type at 1x on a 2x screen is soft, and this scene is cheap: six
     Gaussians and two noise lookups a pixel. */
  pixelRatio: 2,
  params: [
    { key: "cell", label: "Type size", min: 6, max: 40, step: 1, default: 15 },
    { key: "ink", label: "Type strength", min: 0, max: 1, step: 0.01, default: 0.42 },
    { key: "density", label: "Density", min: 0.2, max: 4, step: 0.05, default: 1.6 },
    { key: "floor", label: "Floor", min: 0, max: 0.6, step: 0.01, default: 0.06 },
    { key: "scatter", label: "Scatter", min: 0, max: 1.5, step: 0.01, default: 0.55 },
    { key: "shimmer", label: "Shimmer", min: 0, max: 6, step: 0.1, default: 0.75 },
    { key: "exposure", label: "Exposure", min: 0.2, max: 4, step: 0.05, default: 1.25 },
    { key: "spread", label: "Spread", min: 0.3, max: 2.5, step: 0.05, default: 0.85 },
    { key: "warp", label: "Warp", min: 0, max: 2, step: 0.05, default: 0.6 },
    { key: "wave", label: "Wave", min: 0, max: 3, step: 0.05, default: 1 },
    { key: "drift", label: "Drift", min: 0, max: 3, step: 0.05, default: 1.4 },
    { key: "mosaic", label: "Mosaic", min: 0, max: 1, step: 0.01, default: 0 },
    { key: "rise", label: "Height", min: -0.45, max: 0.45, step: 0.01, default: 0 },
  ],
  glsl: /* glsl */ `
/* A theme's ambient tones can be muted; pushed from their own grey and up
   to full brightness they still read as hues once they are light. */
vec3 glyphHue(vec3 c) {
  float grey = (c.r + c.g + c.b) / 3.0;
  c = max(grey + (c - grey) * 1.8, vec3(0.0));
  return c / max(max(c.r, max(c.g, c.b)), 1e-3);
}

/* One stretched Gaussian light: centre in 0 to 1 across and up the stage,
   half extents along and across its own axis in stage heights, a tilt. */
float glyphLamp(vec2 p, float aspect, vec2 centre, vec2 extent, float tilt, float k, float t) {
  vec2 c = (centre - 0.5) * vec2(aspect, 1.0);
  c += u_drift * 0.05 * vec2(sin(t * 0.13 + k * 1.7), cos(t * 0.11 + k * 2.3));
  float a = tilt + u_drift * 0.06 * sin(t * 0.09 + k * 1.3);
  vec2 d = p - c;
  d = vec2(cos(a) * d.x + sin(a) * d.y, -sin(a) * d.x + cos(a) * d.y) / (extent * u_spread);
  return (1.0 + u_drift * 0.12 * sin(t * 0.21 + k * 2.9)) * exp(-dot(d, d));
}

/* The light at a pixel, tone-mapped. */
vec3 glyphLight(vec2 frag, float t) {
  float aspect = u_size.x / u_size.y;
  vec2 p = (frag / u_size - 0.5) * vec2(aspect, 1.0);
  p.y -= u_rise;
  p += u_warp * 0.09 * (vec2(vnoise(p * 1.6 + t * 0.05), vnoise(p * 1.6 + 7.3 - t * 0.04)) - 0.5);
  /* Slow travelling swells, so the streak rolls like a ribbon. */
  p.y += u_wave * (0.045 * sin(p.x * 2.6 + t * 0.35) + 0.025 * sin(p.x * 5.3 - t * 0.27 + 1.7));
  p.x += u_wave * 0.03 * sin(p.y * 3.1 + t * 0.22);

  vec3 haze = glyphHue(u_col[0]);
  vec3 bloom = glyphHue(u_col[1]);
  vec3 streak = glyphHue(u_col[2]);
  vec3 low = glyphHue(u_col[3]);
  vec3 foot = glyphHue(u_col[4]);
  vec3 core = mix((haze + bloom + streak + low + foot) / 5.0, vec3(1.0), 0.85);

  vec3 c = u_ground;
  c += haze * 0.55 * glyphLamp(p, aspect, vec2(0.47, 0.62), vec2(0.95, 0.3), 0.05, 0.0, t);
  c += bloom * 0.95 * glyphLamp(p, aspect, vec2(0.66, 0.74), vec2(0.5, 0.17), 0.2, 1.0, t);
  c += core * 1.7 * glyphLamp(p, aspect, vec2(0.68, 0.625), vec2(0.3, 0.045), 0.0, 2.0, t);
  c += streak * 1.5 * glyphLamp(p, aspect, vec2(0.3, 0.585), vec2(0.62, 0.011), 0.0, 3.0, t);
  c += low * 1.0 * glyphLamp(p, aspect, vec2(0.8, 0.42), vec2(0.36, 0.2), -0.7, 4.0, t);
  c += foot * 0.75 * glyphLamp(p, aspect, vec2(0.76, 0.2), vec2(0.4, 0.16), -1.1, 5.0, t);
  return u_ground + (1.0 - exp(-(c - u_ground) * u_exposure));
}

vec3 scene(vec2 uv, float t) {
  vec2 frag = uv * u_size;
  float cellH = max(4.0, floor(u_cell * u_ratio + 0.5));
  vec2 size = vec2(cellH * 0.6, cellH);
  vec2 cell = floor(frag / size);
  vec2 local = fract(frag / size);

  vec3 blocky = glyphLight((cell + 0.5) * size, t);
  vec3 col = mix(glyphLight(frag, t), blocky, u_mosaic);
  /* A mosaic shows its seams. */
  vec2 edge = min(local, 1.0 - local) * size;
  col = mix(col, u_ground, u_mosaic * 0.3 * (1.0 - smoothstep(0.0, 1.5 * u_ratio, min(edge.x, edge.y))));

  float lum = dot(blocky - u_ground, vec3(0.2126, 0.7152, 0.0722));
  float beat = t * u_shimmer;
  int tick = int(mod(floor(beat), 512.0));
  ivec2 at = ivec2(cell) + 2048;
  float roll = mix(rnd(at + tick * ivec2(17, 31)), rnd(at + (tick + 1) * ivec2(17, 31)),
                   smoothstep(0.0, 1.0, fract(beat)));
  float v = (lum - u_floor) / (1.0 - u_floor) * u_density
    + (roll - 0.5) * u_scatter * min(1.0, lum * 6.0 + 0.15);
  float g = max(v, 0.0) * u_glyphCount;
  float first = min(u_glyphCount - 1.0, floor(g));
  float second = min(u_glyphCount - 1.0, first + 1.0);
  float ink = mix(texture(u_glyphs, vec2((first + local.x) / u_glyphCount, local.y)).r,
                  texture(u_glyphs, vec2((second + local.x) / u_glyphCount, local.y)).r,
                  smoothstep(0.25, 0.75, fract(g)));
  return mix(col, vec3(1.0), ink * u_ink * smoothstep(0.0, 0.1, v) * (0.45 + 0.55 * min(1.0, v)));
}
`,
};

/**
 * The prism: light through cut glass. Wedges of light open from a point
 * above the stage and cross the dark at a tilt, dim and diffuse, some
 * wide, some thin, gathered round one place, thinning as they widen and
 * each coming and going in its own time. Each shaft is drawn once per colour role, every
 * role a step further along, as glass bends each wavelength a little more:
 * where the copies overlap they sum to white, and where they part the edge
 * of the shaft breaks into the theme's own spectrum.
 */
export const prism: Scene = {
  id: "prism",
  label: "Prism",
  description: "Wedges of light through glass, their edges split into the theme's spectrum.",
  mode: "dark",
  colours: [
    "--color-ambient-5",
    "--color-ambient-6",
    "--color-ambient-1",
    "--color-ambient-2",
    "--color-ambient-4",
  ],
  params: [
    { key: "position", label: "Position", min: -0.5, max: 0.5, step: 0.01, default: 0.2 },
    { key: "spread", label: "Spread", min: 0.15, max: 2, step: 0.01, default: 0.7 },
    { key: "tilt", label: "Tilt", min: -1, max: 1, step: 0.01, default: -0.22 },
    { key: "fan", label: "Fan", min: 0, max: 3, step: 0.01, default: 1.5 },
    { key: "shafts", label: "Shafts", min: 1, max: 10, step: 0.1, default: 2.8 },
    { key: "sharp", label: "Sharpness", min: 0, max: 1, step: 0.01, default: 0.2 },
    { key: "dispersion", label: "Dispersion", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "glow", label: "Glow", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "drift", label: "Drift", min: 0, max: 3, step: 0.05, default: 1 },
  ],
  glsl: /* glsl */ `
/* A theme's ambient tones can be muted; pushed from their own grey and up
   to full brightness they read as a spectrum once they are light. */
vec3 prismHue(vec3 c) {
  float grey = (c.r + c.g + c.b) / 3.0;
  c = max(grey + (c - grey) * 1.8, vec3(0.0));
  return c / max(max(c.r, max(c.g, c.b)), 1e-3);
}

/* The theme's spectrum, one end to the other. */
vec3 prismSpectrum(float x) {
  float f = clamp(x, 0.0, 1.0) * 4.0;
  int i = int(min(floor(f), 3.0));
  return mix(prismHue(u_col[i]), prismHue(u_col[i + 1]), f - float(i));
}

/* The shafts across their own axis: wide soft ones and thin hard ones. */
float prismShafts(float s, float t) {
  float wide = vnoise(vec2(s * u_shafts * 0.5 + t * 0.021, 3.7));
  float thin = vnoise(vec2(s * u_shafts * 2.4 - t * 0.034, 9.1));
  float wideEdge = mix(0.44, 0.1, u_sharp);
  float thinEdge = mix(0.3, 0.02, u_sharp);
  float soft = smoothstep(0.56, 0.56 + wideEdge, wide);
  /* No two thin shafts are as bright as each other. */
  /* And each comes and goes in its own time. */
  float each = 0.04 + 0.96 * smoothstep(0.3, 0.75, vnoise(vec2(s * u_shafts * 0.9 + 5.3, 1.9 + t * 0.07)));
  soft *= 0.35 + 0.65 * smoothstep(0.25, 0.7, vnoise(vec2(s * u_shafts * 0.4 + 8.1, 6.3 - t * 0.05)));
  float hard = smoothstep(0.7, 0.7 + thinEdge, thin);
  return 0.3 * soft * soft + each * hard * hard;
}

vec3 scene(vec2 uv, float t) {
  float aspect = u_size.x / u_size.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
  t *= u_drift;

  /* Across the shafts, which open as they fall from above. */
  float open = 1.0 + u_fan * (0.5 - p.y);
  float s = (p.x - u_position * aspect + u_tilt * p.y) / open;
  float along = p.y - u_tilt * p.x;
  s += 0.04 * (fbm(vec2(p.x * 0.9 + t * 0.02, p.y * 0.7 - t * 0.015)) - 0.5);

  vec3 light = vec3(0.0);
  vec3 total = vec3(0.0);
  for (int k = 0; k < 14; k++) {
    float x = float(k) / 13.0;
    vec3 hue = prismSpectrum(x);
    light += hue * prismShafts(s + (x - 0.5) * 0.085 * u_dispersion, t);
    total += hue;
  }
  /* Every copy in one place is white light. */
  light /= max(total, vec3(1e-3));

  float gather = exp(-(s * s) / (2.0 * u_spread * u_spread));
  /* Each shaft comes and goes along its length. */
  float reach = 0.35 + 0.65 * smoothstep(0.25, 0.75, fbm(vec2(s * 2.4, along * 0.9 - t * 0.03) + 4.0));
  vec3 haze = (total / 14.0) * 0.0015 * exp(-(s * s) / (2.0 * u_spread * u_spread * 2.5));
  /* A wedge of light thins as it widens, and gives out before the floor. */
  float thinning = pow(1.0 / open, 0.8) * (1.0 + 0.5 * u_fan);
  float fade = mix(1.0, smoothstep(-0.62, 0.2, p.y), min(u_fan, 1.0));
  return u_ground + (light * gather * reach * thinning * fade * 0.3 + haze) * u_glow;
}
`,
};

/**
 * Meteors: a shower over a planet's edge. Stars hold a dark sky; meteors
 * fall across it in lanes at one angle, three depths of them, each a white
 * head with a tail that cools through the theme's colours as it thins; and
 * a planet's limb crosses the foot of the scene, lit to a crescent by a sun
 * that flares where it clears the edge. The limb hides what falls behind it.
 * It is soft by default: the streaks, the crescent and the flare are all
 * blurred, and the sky between them is left all but black.
 */
export const meteors: Scene = {
  id: "meteors",
  label: "Meteors",
  description: "A meteor shower over a planet's edge, a sun flaring on the limb.",
  mode: "dark",
  colours: [
    "--color-ambient-2",
    "--color-ambient-3",
    "--color-ambient-5",
    "--color-ambient-1",
    "--color-ambient-4",
  ],
  params: [
    { key: "crown", label: "Limb height", min: -0.2, max: 0.7, step: 0.01, default: 0.26 },
    { key: "curve", label: "Flatness", min: 0.8, max: 8, step: 0.1, default: 2.2 },
    { key: "lean", label: "Lean", min: -0.6, max: 0.6, step: 0.01, default: -0.18 },
    { key: "sun", label: "Sun position", min: -0.5, max: 0.5, step: 0.01, default: 0.22 },
    { key: "flare", label: "Flare", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "glow", label: "Glow", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "shower", label: "Shower", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "angle", label: "Fall angle", min: -1.2, max: 1.2, step: 0.01, default: 0.38 },
    { key: "tail", label: "Tail length", min: 0.2, max: 3, step: 0.01, default: 1 },
    { key: "fall", label: "Fall speed", min: 0, max: 3, step: 0.01, default: 1 },
    { key: "stars", label: "Stars", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "soft", label: "Softness", min: 0, max: 2, step: 0.01, default: 1 },
  ],
  glsl: /* glsl */ `
vec3 meteorHue(vec3 c) {
  float grey = (c.r + c.g + c.b) / 3.0;
  c = max(grey + (c - grey) * 1.8, vec3(0.0));
  return c / max(max(c.r, max(c.g, c.b)), 1e-3);
}

vec3 scene(vec2 uv, float t) {
  float aspect = u_size.x / u_size.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y);
  float px = 1.0 / u_size.y;

  vec3 near = meteorHue(u_col[0]);
  vec3 far = meteorHue(u_col[1]);
  vec3 ember = meteorHue(u_col[2]);
  vec3 sunTint = meteorHue(u_col[3]);
  vec3 deep = meteorHue(u_col[4]);

  /* ---- The limb: a circle far larger than the stage, leaning. */
  float radius = u_curve * max(aspect, 1.0);
  vec2 centre = vec2(u_lean * radius, u_crown - radius * sqrt(max(1.0 - u_lean * u_lean, 0.05)));
  float d = length(p - centre) - radius;
  float sky = smoothstep(0.0, 2.0 * px + 0.012 * u_soft, d);
  /* The sun sits on the edge, over its own place across the stage. */
  float sx = u_sun * aspect;
  float reachX = clamp(sx - centre.x, -radius * 0.98, radius * 0.98);
  vec2 sun = vec2(sx, centre.y + sqrt(radius * radius - reachX * reachX) + 0.004);
  vec2 r = p - sun;
  float fromSun = length(r);
  float lit = exp(-fromSun / 0.55);
  float litWide = exp(-fromSun / 1.4);

  vec3 light = vec3(0.0);

  /* ---- Stars, one to a cell at most. */
  vec2 frag = uv * u_size;
  ivec2 cell = ivec2(floor(frag / 30.0));
  vec2 at = (vec2(cell) + 0.15 + 0.7 * vec2(rnd(cell + 37), rnd(cell + 71))) * 30.0;
  float sd = length(frag - at);
  float pick = rnd(cell + 911);
  float star = exp(-(sd * sd) / (2.0 * 0.7 * 0.7)) * step(0.74, pick) * 0.32
    * (0.25 + 0.75 * pow(rnd(cell + 5), 3.0))
    * (0.7 + 0.3 * sin(t * (0.5 + 1.5 * rnd(cell + 13)) + 40.0 * pick));
  light += mix(vec3(1.0), mix(near, far, rnd(cell + 3)), 0.3) * star * u_stars * (1.0 - 0.8 * exp(-fromSun / 0.18));

  /* ---- The shower: lanes across the fall, three depths of them. */
  vec2 dir = vec2(-sin(u_angle), -cos(u_angle));
  vec2 q = vec2(p.x, p.y - 0.5);
  float a = dot(q, vec2(-dir.y, dir.x));
  float b = dot(q, dir);
  float span = 2.0 + aspect;
  for (int i = 0; i < 3; i++) {
    float depth = 1.0 + float(i) * 0.7;
    float laneW = 0.13 / depth;
    float lane = floor(a / laneW);
    ivec2 id = ivec2(int(lane) + 2048, i * 57 + 3);
    float u = t * u_fall * (0.1 + 0.16 * rnd(id)) / depth + rnd(id + 11) * 17.0;
    ivec2 pass = id + ivec2(0, int(mod(floor(u), 512.0)) * 131 + 7);
    float there = step(1.0 - 0.7 * u_shower, rnd(pass + 5));
    float head = (fract(u) - 0.5) * span;
    float ax = (lane + 0.2 + 0.6 * rnd(pass + 9)) * laneW;
    float len = u_tail * (0.16 + 0.34 * rnd(pass + 13)) / depth;
    float back = (head - b) / len;
    float w = max((0.0011 + 0.0012 * rnd(pass + 17)) * (1.0 + 0.5 * u_soft) / depth, 0.6 * px) * (1.0 - 0.5 * clamp(back, 0.0, 1.0));
    float across = exp(-pow((a - ax) / w, 2.0) * 0.5);
    float trail = smoothstep(-3.0 * w / len, 0.25 * u_soft, back) * pow(max(1.0 - back, 0.0), 1.6);
    vec3 tint = mix(vec3(1.0), near, smoothstep(0.0, 0.22, back));
    tint = mix(tint, ember, smoothstep(0.2, 0.6, back));
    tint = mix(tint, far, smoothstep(0.55, 1.0, back));
    light += tint * across * trail * there * (0.3 + 0.7 * rnd(pass + 21)) * 0.55 / (1.0 + 1.2 * u_soft) / sqrt(depth);
  }

  /* ---- Air on the limb: a thin wash, cool away from the sun. */
  vec3 air = mix(far, near, lit);
  light += air * lobe(d - 0.012, 0.06, 0.02) * (0.015 + 0.08 * litWide) * u_glow;
  light += deep * lobe(d, 0.3, 0.05) * 0.012 * litWide * u_glow;
  light *= sky;

  /* ---- The planet's lit edge: a band of light with no line in it, wide
     by the sun and thinning to nothing away from it. */
  float blur = 0.004 + 0.02 * u_soft;
  float litMid = exp(-fromSun / 0.75);
  float band = lobe(d + 0.3 * blur, blur * (0.12 + 1.1 * litMid), blur * (0.15 + 1.9 * litMid));
  vec3 edge = mix(air, vec3(1.0), 0.3 + 0.55 * litMid);
  light += edge * band * (0.06 + 0.6 * litMid * litMid) * u_glow;

  /* ---- The sun: a soft core, a bloom, and four short spikes that the
     softness melts into it. */
  float coreR = 0.01 + 0.008 * u_soft;
  float core = exp(-dot(r, r) / (2.0 * coreR * coreR));
  float bloom = exp(-dot(r, r) / (2.0 * 0.07 * 0.07)) * 0.3 + exp(-fromSun / 0.16) * 0.1;
  vec2 k = vec2(r.x + r.y, r.x - r.y) * 0.7071;
  float thick = 0.006 + 0.012 * u_soft;
  float spikes = exp(-pow(k.x / thick, 2.0) * 0.5) * exp(-abs(k.y) / 0.09)
    + exp(-pow(k.y / thick, 2.0) * 0.5) * exp(-abs(k.x) / 0.09);
  float veil = mix(0.5, 1.0, sky);
  light += mix(sunTint, vec3(1.0), 0.85) * (core * 0.55 + spikes * 0.6 / (1.0 + u_soft) * veil) * u_flare;
  light += mix(sunTint, vec3(1.0), 0.7) * bloom * veil * u_flare;

  return u_ground + light;
}
`,
};

/**
 * Waves: a sea drawn in points, seen from above it. A plane of dots runs off
 * into mist and rolls in slow swells, each dot a round point that grows and brightens on a
 * crest and all but goes out in a trough, over a glow that lies in the
 * water under them. The surface is found by marching the eye's ray through
 * the slab the swells can occupy, so a near crest hides the trough behind
 * it; each dot is then drawn round on the screen from its own place on the
 * surface. Far off, where the dots would be finer than a pixel, they melt
 * into the glow rather than shimmer.
 */
export const waves: Scene = {
  id: "waves",
  label: "Waves",
  description: "A sea of points rolling off into mist, bright on the crests, over a deep glow.",
  mode: "dark",
  colours: ["--color-ambient-4", "--color-ambient-3", "--color-ambient-2"],
  params: [
    { key: "rise", label: "Height", min: -0.3, max: 0.9, step: 0.01, default: 0.12 },
    { key: "pitch", label: "View", min: 0.15, max: 1.2, step: 0.01, default: 0.3 },
    { key: "swell", label: "Swell", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "reach", label: "Wave length", min: 0.4, max: 3, step: 0.01, default: 1 },
    { key: "density", label: "Density", min: 3, max: 30, step: 0.5, default: 16 },
    { key: "dot", label: "Dot size", min: 0.3, max: 2, step: 0.01, default: 1 },
    { key: "glow", label: "Glow", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "mist", label: "Reach", min: 0.2, max: 3, step: 0.01, default: 1 },
    { key: "flow", label: "Flow", min: 0, max: 3, step: 0.01, default: 1 },
  ],
  glsl: /* glsl */ `
vec3 waveHue(vec3 c) {
  float grey = (c.r + c.g + c.b) / 3.0;
  c = max(grey + (c - grey) * 1.8, vec3(0.0));
  return c / max(max(c.r, max(c.g, c.b)), 1e-3);
}

const float WAVE_LENS = 1.6;

/* The sea's height at a place on the plane, -1 to 1. */
float waveHeight(vec2 q, float t) {
  q /= u_reach;
  float h = 0.5 * sin(dot(q, vec2(0.62, 0.78)) * 1.15 + t * 0.3)
    + 0.28 * sin(dot(q, vec2(-0.74, 0.55)) * 2.1 - t * 0.23 + 1.3)
    + 0.7 * (vnoise(q * 0.5 + vec2(0.0, t * 0.05)) - 0.5);
  return h / 1.13;
}

vec3 scene(vec2 uv, float t) {
  float aspect = u_size.x / u_size.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y - u_rise);
  float px = 1.0 / u_size.y;
  t *= u_flow;

  vec3 deep = waveHue(u_col[0]);
  vec3 smoke = waveHue(u_col[1]);
  vec3 crest = mix(mix(deep, waveHue(u_col[2]), 0.25), vec3(1.0), 0.65);

  /* An eye one unit over the plane, looking down at it by the pitch. The
     ray through this pixel falls by 'fall' and runs out by 'run' a step. */
  float cp = cos(u_pitch);
  float sp = sin(u_pitch);
  float fall = WAVE_LENS * sp - p.y * cp;
  float run = WAVE_LENS * cp + p.y * sp;
  float amp = 0.3 * u_swell;
  float farZ = 6.6 * u_mist;
  vec3 light = vec3(0.0);

  if (fall > 1e-4 && run > 1e-4) {
    /* The ray can only meet the sea inside the slab the swells occupy. */
    float enter = (1.0 - amp) / fall;
    float leave = min((1.0 + amp) / fall, 2.5 * farZ / run);
    float k = enter;
    float last = enter;
    float stride = max(leave - enter, 0.0) / 28.0;
    for (int i = 0; i < 28; i++) {
      float over = (1.0 - fall * k) - amp * waveHeight(vec2(p.x * k, run * k), t);
      if (over < 0.0) break;
      last = k;
      k += stride;
    }
    k = min(k, leave);
    /* Close in on the surface between the last two steps. */
    for (int i = 0; i < 5; i++) {
      float mid = 0.5 * (last + k);
      float over = (1.0 - fall * mid) - amp * waveHeight(vec2(p.x * mid, run * mid), t);
      if (over < 0.0) k = mid; else last = mid;
    }

    vec2 at = vec2(p.x * k, run * k);
    float z = at.y;
    float h = waveHeight(at, t);
    float lift = smoothstep(-0.7, 0.8, h);
    /* Black takes the far sea, and starkly: the dots go first, over a
       short run, and the glow under them a little further out. The near
       edge eases in. */
    float nearEdge = smoothstep(0.0, 0.08, uv.y);
    float fog = exp(-pow(z / (0.8 * farZ), 4.0)) * nearEdge;
    float dotFog = exp(-pow(z / (0.56 * farZ), 6.0)) * nearEdge;

    /* The glow in the water, smoky, brighter under a crest. */
    float cloud = fbm(at * 0.3 + vec2(t * 0.03, -t * 0.02));
    vec3 body = mix(deep, smoke, 0.3 * smoothstep(0.35, 0.75, cloud));
    light += body * (0.04 + 0.22 * lift * lift) * (0.35 + 0.9 * cloud) * fog * u_glow;

    /* The dots: this row's and the rows before and behind it, each drawn
       round on the screen from its own place on the surface. */
    float cellW = 1.0 / u_density;
    float row = floor(z / cellW);
    float dots = 0.0;
    vec2 before = p;
    vec2 behind = p;
    for (int j = -1; j <= 1; j++) {
      float cz = (row + float(j) + 0.5) * cellW;
      /* Where this ray is when it is that far out, to pick the column. */
      float kz = cz / run;
      /* Every other row sits half a cell across, like a halftone. */
      float stagger = 0.5 * mod(row + float(j), 2.0);
      float cx = (floor(p.x * kz / cellW - stagger) + 0.5 + stagger) * cellW;
      float ch = waveHeight(vec2(cx, cz), t);
      float cy = amp * ch - 1.0;
      float depth = max(cz * cp - cy * sp, 1e-3);
      vec2 on = vec2(cx, cy * cp + cz * sp) * WAVE_LENS / depth;
      if (j == -1) before = on;
      if (j == 1) behind = on;
      float up = smoothstep(-0.7, 0.8, ch);
      float rad = 0.15 * cellW * u_dot * (0.4 + 0.6 * up) * WAVE_LENS / depth;
      float shown = max(rad, 0.75 * px);
      float disc = 1.0 - smoothstep(shown - px, shown + px, length(p - on));
      dots = max(dots, disc * (rad * rad) / (shown * shown) * (0.1 + 0.9 * up * up));
    }
    /* Where rows are finer than the pixels, the dots become their average. */
    float rowPx = 0.5 * length(behind - before) / px;
    float even = 0.06 * u_dot * u_dot * (0.1 + 0.9 * lift * lift);
    dots = mix(even, dots, smoothstep(1.5, 3.5, rowPx));
    light += mix(deep, crest, 0.3 + 0.7 * lift) * dots * dotFog * 1.3;
  }
  return u_ground + light;
}
`,
};

/**
 * The aurora: silk in colour, the one scene with no dark in its middle.
 * A plane is folded over itself by slow sine warps, each fold feeding the
 * next, and the folded plane picks the theme's tones in wide soft ribbons:
 * a base tone, three more laid through it, a pale bloom where two ribbons
 * cross, and a void, one deep pool the ground shows through, which is what
 * gives the colour its depth. Nothing in it has an edge.
 */
export const aurora: Scene = {
  id: "aurora",
  label: "Aurora",
  description: "Wide ribbons of the theme's colour folding through one another, round a deep void.",
  mode: "dark",
  colours: [
    "--color-ambient-4",
    "--color-ambient-3",
    "--color-ambient-5",
    "--color-ambient-2",
    "--color-ambient-6",
  ],
  params: [
    { key: "scale", label: "Scale", min: 0.3, max: 3, step: 0.01, default: 1 },
    { key: "fold", label: "Folds", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "tilt", label: "Tilt", min: -1.6, max: 1.6, step: 0.01, default: 0.5 },
    { key: "void", label: "Void", min: 0, max: 1, step: 0.01, default: 0.8 },
    { key: "bloom", label: "Bloom", min: 0, max: 1, step: 0.01, default: 0.6 },
    { key: "bright", label: "Brightness", min: 0.1, max: 1.5, step: 0.01, default: 0.8 },
    { key: "drift", label: "Drift", min: 0, max: 3, step: 0.05, default: 1 },
  ],
  glsl: /* glsl */ `
vec3 auroraHue(vec3 c) {
  float grey = (c.r + c.g + c.b) / 3.0;
  c = max(grey + (c - grey) * 1.6, vec3(0.0));
  return c / max(max(c.r, max(c.g, c.b)), 1e-3);
}

vec3 scene(vec2 uv, float t) {
  float aspect = u_size.x / u_size.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
  t *= u_drift;
  float ca = cos(u_tilt);
  float sa = sin(u_tilt);
  vec2 w = vec2(ca * p.x + sa * p.y, -sa * p.x + ca * p.y) * 2.3 * u_scale;

  /* Fold the plane: each warp bends it along the last one's grain. */
  for (int i = 1; i <= 4; i++) {
    float n = float(i);
    w.x += u_fold * 0.6 / n * sin(n * 1.25 * w.y + t * 0.11 + n * 1.7);
    w.y += u_fold * 0.5 / n * cos(n * 1.05 * w.x - t * 0.09 + n * 2.3);
  }

  float a = 0.5 + 0.5 * sin(w.x * 1.15 + w.y * 0.5 + t * 0.05);
  float b = 0.5 + 0.5 * sin(w.y * 1.35 - w.x * 0.45 + 2.1 - t * 0.04);
  float c = 0.5 + 0.5 * sin((w.x + w.y) * 0.85 + 4.2 + t * 0.03);
  float e = 0.5 + 0.5 * sin(w.x * 0.6 - w.y * 0.95 + 0.7);

  vec3 base = auroraHue(u_col[0]);
  vec3 col = base;
  col = mix(col, auroraHue(u_col[1]), smoothstep(0.3, 0.9, a) * 0.8);
  col = mix(col, mix(auroraHue(u_col[3]), vec3(1.0), 0.25), smoothstep(0.35, 0.95, c) * 0.6);
  col = mix(col, auroraHue(u_col[2]), smoothstep(0.6, 1.0, b) * 0.8);
  col = mix(col, auroraHue(u_col[4]), smoothstep(0.7, 1.0, e) * smoothstep(0.5, 0.9, b) * 0.6);
  /* A pale bloom where ribbons cross. */
  col = mix(col, vec3(1.0), u_bloom * smoothstep(0.25, 0.95, a * c + 0.35 * e) * 0.85);

  /* The void, with the base tone deepening toward it. */
  float pool = 0.5 + 0.5 * sin(w.x * 0.75 - w.y * 1.1 + 5.3 + t * 0.02);
  float dark = u_void * smoothstep(0.5, 0.95, pool);
  col = mix(col, base * 0.5, smoothstep(0.0, 0.6, dark) * 0.7);
  float lit = 1.0 - smoothstep(0.35, 1.0, dark);
  return u_ground + col * lit * u_bright;
}
`,
};

/** Every scene, in picker order. */
export const SCENES = [horizon, rift, glyphs, prism, meteors, waves, aurora];

/**
 * The playground's shader vocabulary (the Shaders view, and the ground it
 * lays under every view). A scene is one look (a horizon, a blob field); a pass is a finishing step any scene can take (grain, a fade, a
 * vignette); a recipe is a scene, its settings, and which passes are on
 * with theirs. Every setting is declared as data, so the panel draws its
 * sliders from the declaration and never needs a hand-built control.
 */

/** One numeric setting, drawn as a slider. */
export type ParamSpec = {
  key: string;
  label: string;
  min: number;
  max: number;
  step: number;
  default: number;
};

/**
 * A look. `glsl` defines `vec3 scene(vec2 uv, float t)`, returning the
 * final linear colour of the pixel over the page ground (`u_ground`). Its
 * settings arrive as `uniform float u_<key>`, and its colours as
 * `u_col[i]` in the order `colours` lists their tokens.
 */
export type Scene = {
  id: string;
  label: string;
  description: string;
  /** Colour tokens, resolved from the live cascade into `u_col[0..]`. */
  colours: string[];
  /**
   * `dark` for a scene that only reads on a dark ground (it adds light).
   * On a light page its surface paints a near-black ground of its own
   * (coloursFor), rather than setting data-theme on itself: a nested
   * [data-theme] matches the base dark tokens and would hide the theme
   * preset's colours.
   */
  mode?: "dark";
  /**
   * A ramp of characters, thin to heavy, for a scene that prints type. The
   * renderer draws it once into a strip texture in the theme's code face
   * (`--font-family-code`) and hands it to the GLSL as `u_glyphs`, with
   * the number of characters in `u_glyphCount`.
   */
  glyphs?: string;
  /**
   * The most drawing-buffer pixels per CSS pixel the scene may use, for a
   * scene with detail finer than soft light (type). Defaults to 1; the
   * ratio in use reaches the GLSL as `u_ratio`.
   */
  pixelRatio?: number;
  params: ParamSpec[];
  glsl: string;
};

/**
 * A finishing step. `glsl` defines one function named `pass_<id>`: a
 * `light` pass takes and returns the linear colour, before encoding; an
 * `srgb` pass takes and returns the encoded colour. Its settings arrive as
 * `uniform float u_<id>_<key>`, and `u_<id>_on` switches it.
 */
export type Pass = {
  id: string;
  label: string;
  stage: "light" | "srgb";
  on: boolean;
  params: ParamSpec[];
  glsl: string;
};

/** What the canvas reads every frame. A ref holds it, so a drag never renders. */
export type Values = {
  speed: number;
  scene: Record<string, number>;
  passes: Record<string, { on: boolean; params: Record<string, number> }>;
};

/** A recipe as it is copied out: the scene's id with the values above. */
export type Recipe = Values & { sceneId: string };

export const MAX_COLOURS = 8;

export function defaultsFor(params: ParamSpec[]) {
  return Object.fromEntries(params.map((param) => [param.key, param.default]));
}
